**Version Used**: 5.11.0-1.26405.2

**Steps to Reproduce**:

Execute the following code:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.MSBuild;

static string CreateCodeFile()
{
    var code = """
    #:property TargetFramework=netstandard2.0
    //#:property TargetFramework=net472
    #:property LangVersion=14.0
    #:property PublishAot=false
    #:property OutputType=Library

    using System;

    public struct MyConsole
    {
        public static void PrintLine()
        {
            Console.WriteLine();
        }
    }
    """;
    var path = Path.Combine(Path.GetTempPath(), "app.cs");

    using var file = new FileStream(path, FileMode.Create);
    using var writer = new StreamWriter(file, Encoding.UTF8);
    writer.Write(code);
    return path;
}

Compilation CreateCompilation(string filePath)
{
    var props = new Dictionary<string, string>();
    //props["Configuration"] = "Release";

    var workspace = MSBuildWorkspace.Create(props);
    var project = workspace.OpenProjectAsync(filePath).Result;
    var errors = false;
    foreach (var d in workspace.Diagnostics)
    {
        if (d.Kind != WorkspaceDiagnosticKind.Failure)
        {
            continue;
        }
        errors = true;
        Console.WriteLine($"{d.Kind}: {d.Message}");
    }
    if (errors)
    {
        throw new Exception("Failed to load project");
    }
    return project.GetCompilationAsync().Result!;
}

var path = CreateCodeFile();
try
{
    var compilation = CreateCompilation(path);
    foreach (var d in compilation.GetDiagnostics())
    {
        if (d.Severity != DiagnosticSeverity.Error)
        {
            continue;
        }
        Console.WriteLine($"{d.Id}: {d.GetMessage()}");
    }
}
finally
{
    File.Delete(path);
}
```


**Diagnostic Id**: CS0400, CS0246 (System... is missing)

**Expected Behavior**:
No compile error

**Actual Behavior**:
the compile error occurs because the reference assemblies are not added (here netstandard2.0). It works for net10.0, net8.0, and other targetFrameworks I have actually installed in (e.g. `C:\Program Files\dotnet\packs\NETStandard.Library.Ref` or `C:\Program Files\dotnet\packs\Microsoft.NETCore.App.Ref`).

